136	// Rollback republishes the full content of an existing historical version
137	// as a new version. History is never deleted or rewritten.
138	func (s *Store) Rollback(org string, expectedVersion, targetVersion int) (int, error) {
139		if org == "" {
140			return 0, ErrMissingOrganization
141		}
142		s.mu.Lock()
143		defer s.mu.Unlock()
144		st := s.orgLocked(org)
145		src, ok := st.versions[targetVersion]
146		if !ok {
147			return 0, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, targetVersion)
148		}
149		if expectedVersion != st.current {
150			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
151		}
152		st.current++
153		snapshot := append([]Policy(nil), src...)
154		st.versions[st.current] = snapshot
155		// A rollback record names the source version in addition to carrying
156		// the full content of the new version.
157		st.appendAuditLocked(org, AuditPolicyChange, &PolicyChange{
158			Version:       st.current,
159			Policies:      snapshot,
160			SourceVersion: targetVersion,
161			RolledBack:    true,
162		}, nil)
163		return st.current, nil
164	}
