// deepConcat joins every string reachable in records for a coarse
// presence probe.
func deepConcat(recs []AuditRecord) string {
	var b strings.Builder
	for _, r := range recs {
		b.WriteString(r.Org)
		b.WriteString(r.Kind)
		if r.Change != nil {
			for _, p := range r.Change.Policies {
				b.WriteString(p.ID)
			}
		}
		if r.Decision != nil {
			b.WriteString(r.Decision.Request.Subject.ID)
		}
	}
	return b.String()
}

