// lastRecordFieldPos walks an archive payload with the production reader and
// returns the offset of the final record's own fingerprint field.
func lastRecordFieldPos(t *testing.T, payload []byte) int {
	t.Helper()
	r := &archiveReader{data: payload}
	r.stringField() // org
	r.u32()         // end seq
	r.stringField() // embedded fingerprint
	n := r.u32()
	if n == 0 || r.err != nil {
		t.Fatal("test fixture has no records")
	}
	var fpPos int
	for i := 0; i < n; i++ {
		r.stringField() // org
		r.u32()         // seq
		r.stringField() // kind
		// Payload pointers are irrelevant here; only positions matter.
		switch r.markerAt() {
		default:
		}
		_ = r
		_ = fpPos
	}
	t.Fatal("unreachable")
	return 0
}

